commit c838c35f2a7e20207879d4881945df1f2bbac4c4
Author: ty <example@example.com>
Date:   Mon Nov 9 17:59:34 2026 +0800

    fix(zs-table): content-scroll 容器横向滚动，修复奇安信旧内核下操作列被裁断(禅道#6358)

    content-scroll 模式下 .el-table 被设为 width:max-content 整体变宽，
    父级 .list-card{overflow:hidden} 直接裁掉变宽部分，导致右侧固定「操作」
    列被窗口右缘截断且无滚动条。给 .zs-table-container--content-scroll
    增加 overflow-x:auto，使变宽表格在容器内横向滚动、操作列可滚动到达。
    现代浏览器内容可放下、该状态不激活，零影响。

diff --git a/src/components/zs-table/zs-table.vue b/src/components/zs-table/zs-table.vue
index 373bfe49e..a9050f8da 100644
--- a/src/components/zs-table/zs-table.vue
+++ b/src/components/zs-table/zs-table.vue
@@ -1335,6 +1335,17 @@ export default {
   isolation: isolate;
 }

+/* 内容宽度超过容器时出现横向滚动条（奇安信可信浏览器等旧内核字体度量略大时更易触发）：
+   content-scroll 模式下 .el-table 被设为 width:max-content 整体变宽，而 .list-card{overflow:hidden}
+   会直接裁掉变宽部分，导致右侧固定「操作」列被窗口右缘截断、且看不到滚动条。
+   改由表格容器自身承担横向滚动：变宽的 .el-table 在容器内滚动，固定操作列可滚动到达，
+   满足「有左右滚动条支持滚动」的验收要求。现代浏览器下内容一般能放下、
+   contentScrollActive 不会激活，此规则零影响。 */
+.zs-table-container--content-scroll {
+  overflow-x: auto;
+  overflow-y: hidden;
+}
+
 .zs-table-container--content-scroll > .el-table {
   width: max-content;
   min-width: 100%;
"}]

